@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        Warehouse.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await AlertService.RefreshAsync(Warehouse.SelectedWarehouseId);
            StartPolling();
        }
    }

    private async Task OnWarehouseChanged()
    {
        StopPolling();
        await AlertService.RefreshAsync(Warehouse.SelectedWarehouseId);
        StartPolling();
        StateHasChanged();
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _timer = null;
    }

    private async Task PollLoopAsync(CancellationToken token)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(token))
            {
                await InvokeAsync(async () =>
                {
                    await AlertService.RefreshAsync(Warehouse.SelectedWarehouseId);
                });
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when navigating away or switching warehouses
        }
    }

    public void Dispose()
    {
        Warehouse.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
        StopPolling();
        _cts?.Dispose();
    }
}

